    /**
     * Method to retrieve the Screening via an ScreeningPrimaryKey.
     * @param 	id Long
     * @return 	Screening
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Screening handle( FindScreeningQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getScreeningId() );
    }
    
    /**
     * Method to retrieve a collection of all Screenings
     *
     * @param	query	FindAllScreeningQuery 
     * @return 	List<Screening> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Screening> handle( FindAllScreeningQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindScreening,
 * but only if the id matches
 *
 * @param		entity	Screening
 */
	protected void emitFindScreening( Screening entity ) {
		LOGGER.info("handling emitFindScreening" );
		
	    queryUpdateEmitter.emit(FindScreeningQuery.class,
	                            query -> query.getFilter().getScreeningId().equals(entity.getScreeningId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllScreening
	 * 
	 * @param		entity	Screening
	 */
	protected void emitFindAllScreening( Screening entity ) {
		LOGGER.info("handling emitFindAllScreening" );
		
	    queryUpdateEmitter.emit(FindAllScreeningQuery.class,
	                            query -> true,
	                            entity);
	}

